import express from 'express';
import {
  getAcademyCourses,
  createCourse,
  updateCourse,
  updateCourseStatus,
  deleteCourse
} from '../controllers/academy.controller.js';
import { protect, adminGuard } from '../middlewares/auth.middleware.js';

const router = express.Router();

// Public route
router.get('/', getAcademyCourses);

// Admin protected routes
router.post('/', protect, adminGuard, createCourse);
router.put('/:id', protect, adminGuard, updateCourse);
router.put('/:id/status', protect, adminGuard, updateCourseStatus);
router.delete('/:id', protect, adminGuard, deleteCourse);

export default router;